INSERT INTO site_content(content_key,payload) VALUES
('hero', '{"eyebrow":"YOUR ENGINEERING PARTNER","headline":"Engineering teams that turn complex ideas into scalable digital products","subheadline":"We help organizations build cloud-native applications, automate delivery pipelines, modernize systems, and accelerate product development.","primaryAction":"Book a consultation","secondaryAction":"View case studies","metrics":[{"label":"Projects delivered","value":"50+","order":1},{"label":"Senior engineers","value":"15+","order":2},{"label":"Platform uptime","value":"99.95%","order":3},{"label":"Engineering support","value":"24/7","order":4}]}'),
('services', '[{"id":1,"title":"Backend Engineering","slug":"backend-engineering","description":"Design and build secure, resilient services and APIs that scale with your product and your customers.","technologies":["Java","Spring Boot","Microservices","Kafka","Redis","PostgreSQL"],"icon":"⌘","order":1},{"id":2,"title":"Frontend Engineering","slug":"frontend-engineering","description":"Deliver fast, accessible digital experiences that make complex products feel effortless.","technologies":["Angular","React","Next.js","TypeScript"],"icon":"◫","order":2},{"id":3,"title":"Cloud & DevOps","slug":"cloud-devops","description":"Build secure cloud foundations and automated delivery workflows that help teams ship with confidence.","technologies":["AWS","Azure","Docker","Kubernetes","Terraform","GitHub Actions"],"icon":"⌁","order":3},{"id":4,"title":"QA Automation","slug":"qa-automation","description":"Integrate intelligent test automation into every stage of delivery for reliable, release-ready software.","technologies":["Playwright","Selenium","JMeter","RestAssured"],"icon":"◎","order":4},{"id":5,"title":"Architecture Consulting","slug":"architecture-consulting","description":"Make the right platform, system design, and scalability decisions before complexity compounds.","technologies":["Cloud native","Event driven","System design","Scalability"],"icon":"✳","order":5}]'),
('technologies', '[{"id":1,"name":"Java","category":"Backend","order":1},{"id":2,"name":"Spring Boot","category":"Backend","order":2},{"id":3,"name":"Angular","category":"Frontend","order":3},{"id":4,"name":"React","category":"Frontend","order":4},{"id":5,"name":"Docker","category":"DevOps","order":5},{"id":6,"name":"Kubernetes","category":"DevOps","order":6},{"id":7,"name":"AWS","category":"Cloud","order":7},{"id":8,"name":"Azure","category":"Cloud","order":8},{"id":9,"name":"Kafka","category":"Backend","order":9},{"id":10,"name":"Redis","category":"Backend","order":10},{"id":11,"name":"Terraform","category":"DevOps","order":11},{"id":12,"name":"PostgreSQL","category":"Data","order":12},{"id":13,"name":"MongoDB","category":"Data","order":13}]'),
('capabilities', '[{"title":"Backend Expertise","description":"Scalable services, distributed systems, and resilient data platforms.","skills":["Java","Spring Boot","Kafka","Redis","PostgreSQL","MongoDB"],"percentage":96,"order":1},{"title":"Frontend Expertise","description":"Accessible, high-performance experiences for modern products.","skills":["Angular","React","Next.js","TypeScript"],"percentage":93,"order":2},{"title":"DevOps Expertise","description":"Cloud infrastructure and automated delivery, built for reliability.","skills":["AWS","Azure","Docker","Kubernetes","Terraform","Jenkins"],"percentage":95,"order":3},{"title":"Testing Expertise","description":"Quality engineering that gives teams confidence to move faster.","skills":["Playwright","Selenium","JMeter","RestAssured"],"percentage":94,"order":4},{"title":"Solution Architects","description":"Pragmatic system design aligned with business goals and growth.","skills":["Cloud native","Event driven","System design","Scalability"],"percentage":97,"order":5}]'),
('process', '[{"title":"Discovery","description":"Align on your goals, users, constraints, and measures of success.","duration":"Week 01","order":1},{"title":"Architecture","description":"Shape a pragmatic technical blueprint and delivery plan with your team.","duration":"Week 01–02","order":2},{"title":"Development","description":"Build in focused iterations with regular demos and transparent progress.","duration":"Ongoing","order":3},{"title":"Testing","description":"Validate functionality, security, performance, and quality continuously.","duration":"Every sprint","order":4},{"title":"Deployment","description":"Release through automated pipelines with observability and rollback readiness.","duration":"Milestone","order":5},{"title":"Support","description":"Keep improving, scaling, and operating your product after launch.","duration":"Long-term","order":6}]'),
('case-studies', '[{"id":1,"title":"Cloud Native Banking Platform","industry":"Financial services","challenge":"A fast-growing financial services team needed to replace a monolithic core that slowed new product launches and limited resilience.","solution":"We partnered with the platform group to introduce domain-aligned services, event-driven workflows, and an automated cloud delivery foundation.","technologies":["Java","Spring Boot","Kafka","Kubernetes","Azure"],"results":[{"label":"Release cadence","value":"4×"},{"label":"Availability","value":"99.99%"}],"order":1},{"id":2,"title":"Enterprise Workflow Solution","industry":"Enterprise SaaS","challenge":"Distributed teams relied on fragmented tools and manual approvals, creating bottlenecks in high-value operational workflows.","solution":"We built a secure, configurable workflow platform with a responsive interface, auditable events, and integrations into existing systems.","technologies":["Angular","Spring Boot","PostgreSQL","Redis","AWS"],"results":[{"label":"Cycle time","value":"−42%"},{"label":"Automation","value":"3.2×"}],"order":2},{"id":3,"title":"E-Commerce Platform","industry":"Digital commerce","challenge":"Seasonal traffic spikes and slow storefront performance were affecting conversion and operations across multiple markets.","solution":"We modernized the storefront and supporting services, then introduced performance testing and elastic cloud deployment practices.","technologies":["React","Java","Docker","Kubernetes","AWS"],"results":[{"label":"Page speed","value":"−58%"},{"label":"Peak traffic","value":"4×"}],"order":3}]'),
('industries', '[{"id":1,"name":"FinTech","description":"Secure platforms that move money, decisions, and markets forward.","icon":"◈","order":1},{"id":2,"name":"Healthcare","description":"Reliable digital experiences designed around care and privacy.","icon":"✚","order":2},{"id":3,"name":"Retail","description":"Connected commerce that brings products closer to people.","icon":"◇","order":3},{"id":4,"name":"Insurance","description":"Modern systems that simplify complex policyholder journeys.","icon":"⬡","order":4},{"id":5,"name":"Logistics","description":"Resilient operations and real-time visibility across supply chains.","icon":"⌁","order":5},{"id":6,"name":"EdTech","description":"Learning products built to make knowledge more accessible.","icon":"▤","order":6}]'),
('testimonials', '[{"id":1,"quote":"Aether helped us move from a roadmap full of technical risk to a platform our teams can confidently build on. They felt like an extension of our engineering organization from the first week.","clientName":"Jordan Lee","clientRole":"VP of Engineering","company":"Northstar Financial","rating":5,"order":1},{"id":2,"quote":"The team brings unusual rigor and genuine partnership. We shipped a complex workflow product on time, and our internal team is now moving faster than before.","clientName":"Morgan Patel","clientRole":"Chief Technology Officer","company":"SonderWorks","rating":5,"order":2},{"id":3,"quote":"Their architecture guidance and delivery discipline made our modernization feel manageable. The impact on performance and release confidence has been tangible.","clientName":"Alex Rivera","clientRole":"Director of Product","company":"Meridian Commerce","rating":5,"order":3}]')
